<?php namespace Agah\Erp\Http;use Agah\Erp\Core\{Ctx,Db,Settings};use Agah\Erp\Modules\Manufacturing\ProductionService;if(!defined('ABSPATH'))exit;$ids=ProductionService::accounts($cid); ?>
<section class="erp-card"><h2>تنظیمات تولید</h2><p>تولید برای شرکت با نوع فعالیت تولیدی و انبار دائمی فعال می‌شود. انتخاب حساب‌ها در همین صفحه است و تنظیم فایل هاست لازم نیست.</p><p>روش فعلی انبار: <?php echo Settings::get('stock_cost_method',$cid)==='fifo'?'FIFO':'میانگین متحرک'; ?>؛ روش حسابداری: <?php echo Settings::get('purchase_goods_mode',$cid)==='inventory'?'موجودی دائمی':'ادواری'; ?>.</p><p>ذخیره تنظیمات، برای شرکت بدون گردش ادواری روش دائمی را فعال می‌کند. روش شرکت دارای گردش ادواری تغییر خودکار نمی‌کند؛ تبدیل مانده‌های مالی نیازمند مهاجرت حسابداری بررسی‌شده است.</p><p>حساب دستمزد و سربار، حساب هزینه‌ای است که قبلاً بدهکار شده؛ هزینه قابل جذب نباید از مانده ثبت‌شده آن در سال و تاریخ تکمیل بیشتر باشد. برای حساب‌های با تفصیلی اجباری، ابتدا معین مناسب تولید را تعریف کنید.</p>
<?php if(Ctx::can('company_settings.edit')):$options=[0=>'انتخاب حساب'];foreach(Db::rows('SELECT id,code,name FROM '.Db::t('accounts').' WHERE company_id=%d AND level=3 AND is_active=1 ORDER BY code',$cid) as $a)$options[$a['id']]=$a['code'].' — '.$a['name']; ?>
<form method="post" class="erp-form"><?php self::form('module_production_setup',$cid,$p);foreach(['wip'=>'کالای در جریان ساخت (دارایی جاری)','labor'=>'انتقال هزینه دستمزد مستقیم','overhead'=>'انتقال هزینه سربار','loss'=>'هزینه ضایعات غیرعادی'] as $k=>$label)self::select($k.'_account_id',$label,$options,$ids[$k]); ?><button type="submit" class="btn btn-primary">ذخیره تنظیمات تولید</button></form><?php endif; ?></section>
